def transpose_transform(input_grid):
    block = [[input_grid[j][i] for j in range(3)] for i in range(3)]
    return block

def hyp2_transform(input_grid):
    # First row from last input row, middle from middle reversed, third from first reversed
    block = [
        input_grid[2][:],
        input_grid[1][::-1],
        input_grid[0][::-1],
    ]
    return block

def hyp3_transform(input_grid):
    # Full transpose with column swap
    block = [
        [input_grid[j][i] for j in range(3)] for i in range(3)
    ]
    return block

